namespace NextStep.Api;

// Reviewed organizer content, never a student-level classifier or prerequisite invention.
// Keep source URL/date in the model context; changes invalidate cached comparisons.
public sealed record LearningOutline(string SourceUrl, string ReviewedAt, string[] Topics, string StartingPoint, string ScopeNote);
public static class ReviewedLearningOutlines {
    public static LearningOutline? Get(string id) => id switch {
        "harvard-cs50-python" => new("https://cs50.harvard.edu/python/", "2026-11-01", ["Python functions and variables", "Conditions and loops", "Exceptions and libraries", "Unit testing", "Reading and writing files", "Regular expressions", "Classes and objects", "Practice problems and a final project"], "Designed for students with or without prior programming experience who want to learn Python. The introduction itself teaches the foundations; previous Python experience is not a prerequisite.", "Published sequence of ten weeks of material; this is not a reported hours-per-week workload or fixed student deadline. Evaluate partial overlap topic by topic, not only the word introductory."),
        "harvard-cs50-web" => new("https://cs50.harvard.edu/web/", "2026-11-01", ["HTML and CSS", "Git", "Python and Django", "SQL, data models and migrations", "JavaScript and user interfaces", "Testing and CI/CD", "Scalability and security", "Hands-on web projects"], "Organizer lists CS50x or prior experience in any programming language as the prerequisite. React alone does not establish Django experience; prior substantial web work may overlap with some topics.", "Compare the student's actual contribution to web-application design and implementation. Do not turn preparation advice into additional organizer entry requirements."),
        "harvard-cs50-sql" => new("https://cs50.harvard.edu/sql/", "2026-11-01", ["Relational queries and table relationships", "Database modeling, types, constraints and triggers", "Normalization", "Primary/foreign keys and joins", "Views and indexes", "Database scaling", "SQLite with introductions to PostgreSQL and MySQL"], "An introduction to databases using SQL. A SQL tag does not demonstrate query depth or schema design; inspect concrete work before calling this repeated material.", "Published seven-week material sequence is not an estimated weekly workload or registration deadline."),
        "google-ml-crash-course" => new("https://developers.google.com/machine-learning/crash-course/prereqs-and-prework", "2026-11-01", ["Core machine-learning concepts", "Practical Python exercises using NumPy, pandas and Keras", "Data and model concepts rather than in-depth tutorials for specific ML APIs"], "No prior ML knowledge is presumed. Organizer recommends programming experience and familiarity with algebra and statistics. Exercises use Python; experienced programmers without Python may still complete them. NumPy/pandas prework is provided; calculus is optional for advanced topics.", "Do not call missing prior ML a blocker. Distinguish the organizer's recommendations and prework from hard participation conditions; evaluate refresh value for students already building models."),
        _ => null
    };
}
